const momentsNode = $('Code - Find Moments');
const base = (momentsNode && momentsNode.first() && momentsNode.first().json) ? momentsNode.first().json : {};
const inItem = $input.first();
const r = (inItem && inItem.json) ? inItem.json : {};

let geminiText = null;
if (Array.isArray(r.candidates) && r.candidates[0]?.content?.parts) {
  const p = r.candidates[0].content.parts.find(pt => pt && pt.text);
  if (p && p.text) geminiText = p.text.trim();
}

let anthropicText = null;
if (Array.isArray(r.content)) {
  const t = r.content.find(b => b && b.type === 'text');
  if (t && t.text) anthropicText = t.text.trim();
}

const aiText = geminiText || anthropicText;
const ok = Boolean(aiText && aiText.length > 0);

return [{ json: {
  stream_id: base.stream_id || r.stream_id,
  moments: base.moments || r.moments || [],
  summary: ok ? aiText.slice(0, 1200) : (base.rule_summary || r.rule_summary || 'Stream concluded successfully.'),
  source: ok ? 'ai' : 'rule',
} }];
